recipes.code:
{
  "inputs": [
    {
      "id": "nextcloud-password",
      "type": "promptString",
      "description": "Nextcloud app password (generate in Nextcloud Security settings)",
      "password": true
    }
  ],
  "servers": {
    "aiquila": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "aiquila-mcp@0.3.23"
      ],
      "env": {
        "NEXTCLOUD_URL": "<nextcloud-url>",
        "NEXTCLOUD_USER": "<nextcloud-user>",
        "NEXTCLOUD_PASSWORD": "${input:nextcloud-password}"
      }
    }
  }
}
